// Para probar a mano: '' elige el corte según la hora; 'AM' arma el de las 10:00 de hoy; 'PM' el de las 16:00 de hoy.
const FORZAR_TURNO = '';
return [{ json: { modo: 'informe', prueba: true, forzar_turno: FORZAR_TURNO } }];

// ======================= CONFIGURACION ÚNICA =======================
// Todo lo que se ajusta del monitoreo está acá. Los demás nodos lo leen de este nodo.
// (El modelo de IA es lo único que se cambia aparte, en los 3 nodos "Modelo IA".)
// El cliente de este archivo es FICTICIO: reemplazá cliente, descripción, reglas, ejemplos y búsquedas por los de tu cliente.
const CONFIG = {
  cliente: 'Ejemplo S.A.',
  cliente_corto: 'EJ',
  descripcion: 'Es una empresa de servicios con sedes y plantas en varias provincias. En los medios también aparece como "Grupo Ejemplo".',
  alias_regex: 'ejemplo s\\.?a\\.?|grupo ejemplo',          // cómo se nombra a la empresa en un titular
  servidor: 'http://host.docker.internal:8787',             // servicio local (pptx + notas guardadas)
  token: 'YOUR_SERVICE_TOKEN',                              // igual al token.txt del servicio
  ping: 'https://hc-ping.com/YOUR_CHECK_UUID',               // healthchecks.io
  feedback_url: 'https://YOUR_N8N_HOST/webhook/media-feedback', // links de corrección del mail
  // Palabras que tiene que tener el titular o la bajada para pasar a la IA
  palabras_clave: 'ejemplo s\\.?a\\.?|grupo ejemplo',
  // Qué cuenta como relevante para este cliente (va dentro del prompt de clasificación)
  reglas_relevancia: 'true si la nota trata sobre la empresa, sus sedes, obras, servicios, precios, seguridad o conflictos, o sobre algo que pasa en sus instalaciones y afecta a sus clientes. También true si nombra a la empresa aunque el hecho no ocurra en sus instalaciones (es reputación). false si la empresa aparece solo de pasada, si es otra empresa con un nombre parecido o un tema sin relación.',
  // Ejemplos para la IA: titular -> clasificación esperada
  ejemplos: [
    '"Ejemplo S.A. invertirá US$10 millones en una nueva planta en el norte del país" -> {"relevante": true, "tema": "infraestructura", "sentimiento": "positivo", "motivo": "anuncio de inversión de la empresa"}',
    '"Paro en la planta de Ejemplo S.A.: qué servicios se ven afectados" -> {"relevante": true, "tema": "operacion", "sentimiento": "negativo", "motivo": "conflicto gremial que afecta el servicio"}',
    '"Grupo Ejemplo suma clientes y marca un récord en el semestre" -> {"relevante": true, "tema": "demanda", "sentimiento": "positivo", "motivo": "crecimiento de clientes de la empresa"}',
    '"Cuánto pueden subir las acciones de los bancos este mes" -> {"relevante": false, "tema": "otros", "sentimiento": "neutral", "motivo": "nota financiera sin relación con el cliente"}',
    '"Un actor fue visto almorzando cerca de una sede de Ejemplo S.A." -> {"relevante": false, "tema": "otros", "sentimiento": "neutral", "motivo": "la empresa aparece de pasada"}'
  ],
  // Palabras del rubro que no sirven para distinguir una historia de otra
  genericos: 'ejemplo grupo empresa planta sede',
  // Búsquedas en agregadores
  google: ['"Ejemplo S.A."', '"Grupo Ejemplo"', '"Ejemplo S.A." inversión', '"Ejemplo S.A." conflicto'],
  bing: ['"Ejemplo S.A."', '"Grupo Ejemplo"'],
  // RSS directos de medios (traen solo las últimas horas: por eso se recolecta cada hora)
  medios: {
    'Infobae': 'https://www.infobae.com/arc/outboundfeeds/rss/?outputType=xml',
    'La Nación': 'https://www.lanacion.com.ar/arc/outboundfeeds/rss/?outputType=xml',
    'Clarín': 'https://www.clarin.com/rss/lo-ultimo/',
    'Ámbito': 'https://www.ambito.com/rss/pages/home.xml',
    'Perfil': 'https://www.perfil.com/feed',
    'El Cronista': 'https://www.cronista.com/arc/outboundfeeds/rss/?outputType=xml',
    'TN': 'https://tn.com.ar/arc/outboundfeeds/rss/?outputType=xml',
    'MDZ Online': 'https://www.mdzol.com/rss/pages/home.xml',
    'Minuto Uno': 'https://www.minutouno.com/rss/pages/home.xml',
    'La Capital': 'https://www.lacapital.com.ar/rss/pages/home.xml'
  }
};
// ===================================================================
return $input.all().map(i => ({ json: Object.assign({}, i.json, { cfg: CONFIG }) }));

// Calcula la ventana del corte y arma una consulta por fuente.
// Ventanas sin huecos: AM = 15:45 del día hábil anterior a 9:45; PM = 9:45 a 15:45 (el flujo corre a esas horas, de lunes a viernes).
const entrada = $input.first().json;
if (!entrada.modo) return []; // vino del webhook de correcciones: no es para este camino
const CONFIG = entrada.cfg;
const modo = entrada.modo || 'informe';
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const H = 3 * 3600 * 1000; // Argentina: UTC-3 todo el año
const ahora = new Date().getTime();
const loc = new Date(ahora - H);
const y = loc.getUTCFullYear(), m = loc.getUTCMonth(), d = loc.getUTCDate();
const at = (dia, hora, min) => Date.UTC(y, m, dia, hora, min, 0) + H;
const minutos = loc.getUTCHours() * 60 + loc.getUTCMinutes();
let turno = entrada.forzar_turno === 'AM' || entrada.forzar_turno === 'PM' ? entrada.forzar_turno : (minutos < 12 * 60 ? 'AM' : 'PM');
let corte, desde, hasta;
// Informes solo de lunes a viernes: el AM del lunes cubre desde el viernes a las 15:45 (todo el fin de semana).
const esLunes = loc.getUTCDay() === 1;
if (turno === 'AM') { corte = '10:00'; desde = at(d - (esLunes ? 3 : 1), 15, 45); hasta = at(d, 9, 45); }
else { corte = '16:00'; desde = at(d, 9, 45); hasta = at(d, 15, 45); }
const lunesAM = esLunes && turno === 'AM';
const base = { lunesAM, modo, prueba: !!entrada.prueba, cfg: CONFIG, cliente: CONFIG.cliente, cliente_corto: CONFIG.cliente_corto, turno, corte, desde, hasta, ahora,
  fecha: d + ' de ' + MESES[m] + ' de ' + y };
const fuentes = [];
for (const q of CONFIG.google) fuentes.push({ fuente: 'Google News: ' + q, tipo: 'google', medio_fijo: '',
  url: 'https://news.google.com/rss/search?q=' + encodeURIComponent(q + (lunesAM ? ' when:4d' : ' when:2d')) + '&hl=es-419&gl=AR&ceid=AR:es-419' });
for (const q of CONFIG.bing) fuentes.push({ fuente: 'Bing News: ' + q, tipo: 'bing', medio_fijo: '',
  url: 'https://www.bing.com/news/search?q=' + encodeURIComponent(q) + '&format=rss&setlang=es-AR&cc=AR&qft=sortbydate%3d%221%22' });
for (const [nombre, url] of Object.entries(CONFIG.medios)) fuentes.push({ fuente: nombre, tipo: 'medio', medio_fijo: nombre, url });
return fuentes.map(f => ({ json: Object.assign({}, base, f) }));

// Lee todas las fuentes, normaliza, filtra por palabras clave, guarda en el servicio local y arma la lista del corte.
const http = (typeof $helpers !== 'undefined' && $helpers.httpRequest) ? $helpers : this.helpers;
const fuentes = $('Fuentes y ventana').all().map(x => x.json);
const info = fuentes[0];
const SERVIDOR = info.cfg.servidor;
const AUTH = { 'X-Token': info.cfg.token };
const CLAVE = new RegExp(info.cfg.palabras_clave, 'i');
const recolectando = info.modo === 'recolectar';
// En la recolección horaria un problema no manda mail: lo detecta el informe siguiente.
const falla = msg => { if (recolectando) return null; throw new Error(msg); };
const dec = s => s.replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#x27;|&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const limpiar = s => dec(dec(s)).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const norm = s => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const hhmm = t => { const x = new Date(t - 3 * 3600 * 1000); return String(x.getUTCHours()).padStart(2, '0') + ':' + String(x.getUTCMinutes()).padStart(2, '0'); };
// Hora de la nota; si es de otro día que el corte (ej. el lunes, notas del fin de semana), con el día adelante: "sáb 14:30"
const DIAS = ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'];
const diaAR = t => new Date(t - 3 * 3600 * 1000).toISOString().slice(0, 10);
const cuando = t => (diaAR(t) === diaAR(info.hasta - 1) ? '' : DIAS[new Date(t - 3 * 3600 * 1000).getUTCDay()] + ' ') + hhmm(t);
const ok = [], fallidas = [];
let leidas = 0, porPalabra = 0;
const frescas = [];
$input.all().forEach((it, i) => {
  const f = fuentes[i];
  const xml = it.json.xml;
  if (typeof xml !== 'string' || !/<item[\s>]/.test(xml)) { fallidas.push(f.fuente); return; }
  ok.push(f.fuente);
  for (const raw of (xml.match(/<item[\s>][\s\S]*?<\/item>/g) || [])) {
    leidas++;
    const get = tag => { const mm = raw.match(new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + tag + '>')); return mm ? limpiar(mm[1]) : ''; };
    let titulo = get('title');
    let medio = f.medio_fijo || get('source') || get('News:Source');
    let link = get('link');
    const t = Date.parse(get('pubDate') || get('dc:date'));
    const desc = get('description').slice(0, 300);
    if (f.tipo === 'bing') { const u = link.match(/[?&]url=([^&]+)/); if (u) link = decodeURIComponent(u[1]); }
    if (!medio) { const k = titulo.lastIndexOf(' - '); if (k > 0) medio = titulo.slice(k + 3); }
    if (medio && titulo.endsWith(' - ' + medio)) titulo = titulo.slice(0, -(medio.length + 3));
    if (medio && medio.length > 25 && medio.indexOf(' - ') > 2) medio = medio.slice(0, medio.indexOf(' - ')); // "Infobae - Últimas noticias" -> "Infobae"
    if (!titulo || !t || t < Math.min(info.ahora - 48 * 3600e3, info.desde - 6 * 3600e3) || t > info.ahora + 3600e3) continue; // el lunes la ventana abarca el fin de semana
    const descUtil = f.tipo === 'google' || norm(desc) === norm(titulo) ? '' : desc;
    if (!CLAVE.test(titulo + ' ' + descUtil)) { porPalabra++; continue; }
    frescas.push({ clave: norm(titulo).slice(0, 90) + '|' + norm(medio || 'sin medio'), titulo, medio: medio || 'Sin medio', link, t, desc: descUtil, via: f.tipo });
  }
});
if (ok.length === 0) { falla('Ninguna fuente respondió (' + fallidas.length + ' fallidas). ¿Hay internet en la Mac?'); return []; }
let guardado;
try { guardado = await http.httpRequest({ method: 'POST', url: SERVIDOR + '/notas', headers: AUTH, body: { notas: frescas }, json: true }); }
catch (e) { falla('No pude guardar en el servicio local. ¿Está corriendo? Probá: curl localhost:8787/health. Detalle: ' + e.message); return []; }
if (recolectando) return [];
let guardadas = [], usadas = new Set(), usadasNotas = [];
try { const r = await http.httpRequest({ method: 'GET', url: SERVIDOR + '/notas?desde=' + info.desde + '&hasta=' + info.hasta + '&tardias=1&corte=' + encodeURIComponent(info.fecha + '|' + info.corte), headers: AUTH, json: true }); const rr = typeof r === 'string' ? JSON.parse(r) : r; guardadas = rr.notas || []; usadas = new Set(rr.usadas || []); usadasNotas = rr.usadas_notas || []; }
catch (e) { throw new Error('No pude leer las notas guardadas del servicio local: ' + e.message); }
const porClave = new Map();
for (const n of guardadas.concat(frescas)) {
  if (usadas.has(n.clave)) continue; // ya se consideró en otro corte: no se cuenta dos veces
  if (!n.tarde && (n.t < info.desde || n.t >= info.hasta)) continue; // ventana [desde, hasta) // las "tarde" son del borde del corte anterior, indexadas después
  const prev = porClave.get(n.clave);
  // Si la misma nota vino por un agregador y por el RSS del medio, me quedo con el link directo
  if (!prev || (prev.via !== 'medio' && n.via === 'medio')) porClave.set(n.clave, Object.assign({}, prev || {}, n));
}
// Segunda pasada de duplicados: mismo link, o título casi igual en el mismo medio (otra fuente lo trajo cortado o retocado)
const toks = t => new Set(norm(t).split(' ').filter(w => w.length > 2));
const compacto = m => norm(m).replace(/ /g, '');
const mismoMedio = (a, b) => { const x = compacto(a), y = compacto(b); return x === y || (x.length > 3 && y.length > 3 && (x.startsWith(y) || y.startsWith(x))); };
// Mismo título si el corto está entero dentro del largo (cortado o con algo agregado), o si en títulos largos coincide el 80% de las palabras.
// En títulos cortos del mismo medio no alcanza el 80%: "Demoras por lluvia en la planta norte" y "Demoras por gremios en la planta norte" son notas distintas.
const parecidos = (a, b) => { const A = toks(a), B = toks(b); let c = 0; for (const w of A) if (B.has(w)) c++; const min = Math.min(A.size, B.size); return (min >= 4 && c === min) || (min >= 8 && c / min >= 0.8); };
const esDup = (u, n) => (u.link && n.link && u.link === n.link) || (mismoMedio(u.medio, n.medio) && Math.abs(u.t - n.t) <= 3 * 3600e3 && parecidos(u.titulo, n.titulo));
const unicas = [];
let duplicadas = 0, yaContadas = 0;
for (const n of [...porClave.values()].sort((a, b) => (a.via === 'medio' ? 0 : 1) - (b.via === 'medio' ? 0 : 1) || a.t - b.t)) {
  if (usadasNotas.some(u => esDup(u, n))) { yaContadas++; continue; } // la misma nota ya se contó en otro corte, traída por otra fuente
  const dup = unicas.find(u => esDup(u, n));
  if (dup) { duplicadas++; continue; }
  unicas.push(n);
}
let notas = unicas.sort((a, b) => b.t - a.t);
const TOPE = info.lunesAM ? 150 : 60; // el lunes junta todo el fin de semana
const recortadas = Math.max(0, notas.length - TOPE);
notas = notas.slice(0, TOPE);
if (notas.length === 0) throw new Error('AVISO: no hubo menciones que pasen el filtro entre las ' + hhmm(info.desde) + ' y las ' + hhmm(info.hasta) + ' (' + leidas + ' notas leídas en ' + ok.length + ' fuentes). No se generó informe.');
const stats = { tardias: notas.filter(n => n.tarde).length, fuentes_ok: ok, fuentes_fallidas: fallidas, leidas, por_palabra: porPalabra, duplicadas, ya_contadas: yaContadas, en_ventana: notas.length, recortadas, guardadas_total: guardado && guardado.total };
return notas.map((n, i) => ({ json: Object.assign({ id: i, hora: cuando(n.t), stats: i === 0 ? stats : undefined }, n, {
  prompt:
`Sos analista senior de monitoreo de medios de una agencia de comunicación. Tu cliente: ${info.cfg.cliente}
${info.cfg.descripcion}

Clasificá esta nota:
Medio: ${n.medio}
Titular: ${n.titulo}
Bajada: ${n.desc || '(sin bajada)'}

Reglas:
- "relevante": ${info.cfg.reglas_relevancia}
- "tema": "infraestructura" (obras, inversiones, nuevas sedes o plantas, financiamiento, deuda), "demanda" (clientes, ventas, precios de mercado, récords, nuevos servicios), "operacion" (demoras, interrupciones, cierres, servicios, tarifas, seguridad, conflictos gremiales), "institucional" (comunicados, aclaraciones o acciones de la empresa fuera de la operación diaria, polémicas sobre su reputación) u "otros".
- "sentimiento": cómo deja parada la nota a la empresa. "positivo" (logros, inversiones, mejoras), "negativo" (problemas, quejas, conflictos, demoras, críticas), "neutral" (informativo).
- "motivo": hasta 12 palabras que expliquen tu decisión.

Ejemplos:
${info.cfg.ejemplos.join('\n')}

Respondé SOLO con el JSON, con las claves relevante, tema, sentimiento y motivo.`
}) }));

const CFG = $('Fuentes y ventana').first().json.cfg;
// Lee la clasificacion de la IA, separa relevantes y descartadas y arma el pedido para agrupar en historias.
const notas = $('Unir, filtrar y guardar').all().map(x => x.json);
const res = $input.all();
const leer = r => { const s = String((r && r.json && (r.json.output ?? r.json.text ?? r.json.response)) ?? ''); const m = s.match(/\{[\s\S]*\}/); return JSON.parse(m ? m[0] : s); };
const TEMAS = ['infraestructura', 'demanda', 'operacion', 'institucional', 'otros'];
const SENT = ['positivo', 'neutral', 'negativo'];
const sinAcento = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const EMPRESA = new RegExp(CFG.alias_regex, 'i');
const rel = [], descartadas = [], sinClasificar = [];
notas.forEach((n, i) => {
  let c = null;
  try {
    const o = leer(res[i]);
    const r = o.relevante === true || o.relevante === 'true' ? true : o.relevante === false || o.relevante === 'false' ? false : null;
    const s = sinAcento(o.sentimiento), t = sinAcento(o.tema);
    if (r !== null && (SENT.includes(s) || r === false)) c = { r, r_ia: r, tema: TEMAS.includes(t) ? t : 'otros', sent: SENT.includes(s) ? s : 'neutral', motivo: String(o.motivo || '').slice(0, 120) };
  } catch (e) {}
  const base = { clave: n.clave, tarde: !!n.tarde, titulo: n.titulo, medio: n.medio, hora: n.hora, t: n.t, link: n.link, desc: n.desc, via: n.via };
  // Regla fija: si el titular nombra a la empresa, es relevante aunque la IA diga que no (es reputación del cliente)
  if (c && !c.r && EMPRESA.test(n.titulo)) { c.r = true; c.motivo = 'nombra a la empresa (regla fija; la IA la había descartado: ' + c.motivo + ')'; }
  if (!c) sinClasificar.push(base);
  else if (!c.r) descartadas.push(Object.assign(base, { motivo: c.motivo, rel_ia: false }));
  else rel.push(Object.assign(base, { tema: c.tema, sent: c.sent, motivo: c.motivo, rel_ia: c.r_ia, regla: c.r !== c.r_ia }));
});
if (sinClasificar.length > notas.length * 0.3) throw new Error('La IA no pudo clasificar ' + sinClasificar.length + ' de ' + notas.length + ' notas. Revisá que Ollama esté corriendo y que el modelo del nodo "Modelo IA" esté descargado.');
if (rel.length === 0 && descartadas.length >= 10) throw new Error('La IA descartó las ' + descartadas.length + ' notas del corte. Puede ser normal, pero es más probable que el modelo o el prompt estén fallando: revisá una de las descartadas. Ejemplos: ' + descartadas.slice(0, 5).map(d => d.titulo + ' (' + d.motivo + ')').join('; '));
if (rel.length === 0) throw new Error('AVISO: ninguna de las ' + notas.length + ' notas del corte resultó relevante para el cliente. Descartadas: ' + descartadas.map(d => d.titulo + ' (' + d.medio + ')').slice(0, 10).join('; '));
rel.sort((a, b) => b.t - a.t);
const lista = rel.slice(0, 40).map((r, i) => '[' + i + '] ' + r.titulo + ' [medio: ' + r.medio + ']' + (r.desc ? ': ' + r.desc.slice(0, 120) : '')).join('\n');
const ctx = { rel, descartadas, sinClasificar, stats: notas[0].stats };
return [{ json: { ctx, prompt:
`Sos analista de monitoreo de medios. Estas son las notas del corte sobre ${CFG.cliente}, numeradas:

${lista}

Agrupá en una misma historia las notas que cuentan el MISMO hecho, aunque lo cuenten desde ángulos distintos. Ejemplos: un paro en una planta, los servicios afectados por ese paro y la respuesta de la empresa son UNA historia; el anuncio de una emisión de deuda y las notas que la analizan son UNA historia; una inversión en una provincia y una queja de clientes en otra son historias SEPARADAS. Cada número va en una sola historia. Una nota sola puede ser su propia historia.

Respondé SOLO con un JSON así: {"historias": [{"nombre": "hecho en pocas palabras", "ids": [0, 3]}, {"nombre": "...", "ids": [1]}]}` } }];

const CFG = $('Fuentes y ventana').first().json.cfg;
// Arma las historias del corte (agrupacion de la IA, con respaldo propio si falla) y pide una tarjeta por historia.
const { ctx } = $('Preparar historias').first().json;
const rel = ctx.rel;
const N = Math.min(rel.length, 40);
const leer = r => { const s = String((r && r.json && (r.json.output ?? r.json.text ?? r.json.response)) ?? ''); const m = s.match(/\{[\s\S]*\}/); return JSON.parse(m ? m[0] : s); };
const STOP = new Set('para como sobre entre desde hasta tras cuando donde porque pero sino este esta estos estas ese esa eso aquel todo todos toda todas otro otra otros otras cual cuales quien quienes cuanto cuantos nuevo nueva nuevos nuevas argentina argentino'.split(' '));
const toks = s => new Set(s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').split(' ').filter(w => w.length >= 4 && !STOP.has(w)));
let grupos = null, agrupoIA = true;
try {
  const o = leer($input.first());
  const usados = new Set();
  grupos = (o.historias || []).map(h => (Array.isArray(h.ids) ? h.ids : []).map(Number).filter(i => Number.isInteger(i) && i >= 0 && i < N && !usados.has(i) && usados.add(i)))
    .filter(g => g.length > 0);
  for (let i = 0; i < N; i++) if (!usados.has(i)) grupos.push([i]);
  if (grupos.length === 0) throw new Error('sin grupos');
} catch (e) {
  agrupoIA = false; grupos = [];
  const tk = rel.slice(0, N).map(r => toks(r.titulo));
  for (let i = 0; i < N; i++) {
    let g = grupos.find(gr => gr.some(j => { let c = 0; for (const w of tk[i]) if (tk[j].has(w)) c++; return c >= 3 || c / Math.max(1, Math.min(tk[i].size, tk[j].size)) >= 0.5; }));
    if (g) g.push(i); else grupos.push([i]);
  }
}
// Control de coherencia: si la IA metió en una historia una nota que no comparte ninguna palabra de contenido
// (titular y bajada) con las demás, se separa como historia propia. Evita que una nota distinta quede escondida en otra tarjeta.
const contenido = r => toks(r.titulo + ' ' + (r.desc || ''));
let separadas = 0;
if (agrupoIA) {
  for (let cambio = true; cambio;) {
    cambio = false;
    for (const g of grupos) {
      if (g.length < 2) continue;
      const k = g.findIndex(i => { const mio = contenido(rel[i]); return !g.some(j => j !== i && [...contenido(rel[j])].some(w => mio.has(w))); });
      if (k !== -1) { grupos.push(g.splice(k, 1)); separadas++; cambio = true; break; }
    }
  }
}
