const firma = s => { let a = 0x811c9dc5, b = 0x5bd1e995; for (let i = 0; i < s.length; i++) { const c = s.charCodeAt(i); a = Math.imul(a ^ c, 0x01000193) >>> 0; b = Math.imul(b ^ c, 0x85EBCA77) >>> 0; } return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0'); };
const TIPOS = { revisado: 'revisaste todo este corte; desde ahora cuenta para medir la calidad', no_relevante: 'no era relevante', si_relevante: 'sí era relevante', positivo: 'el sentiment era positivo', neutral: 'el sentiment era neutral', negativo: 'el sentiment era negativo' };
const pagina = (titulo, texto, ok) => '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:Arial,sans-serif;max-width:480px;margin:40px auto;padding:0 16px"><div style="border-left:5px solid ' + (ok ? '#FF6A13' : '#C62828') + ';padding:8px 14px"><h2 style="margin:0 0 6px">' + titulo + '</h2><p style="color:#444">' + texto + '</p></div><p style="color:#999;font-size:12px">Monitoreo de medios. Podés cerrar esta pestaña.</p></body>';
let html;
if (!q.k || !q.c || !TIPOS[q.v] || q.s !== firma(cfg.token + '|' + q.k + '|' + q.c + '|' + q.v)) {
  html = pagina('Link inválido', 'Este link no es válido o está incompleto. No se registró nada.', false);
} else {
  try {
    await http.httpRequest({ method: 'POST', url: cfg.servidor + '/feedback', headers: { 'X-Token': cfg.token }, body: { clave: q.k, corte: q.c, tipo: q.v }, json: true });
    html = pagina('Corrección registrada', 'Anotado: ' + TIPOS[q.v] + '. Se va a usar para medir la precisión de la IA y mejorar los prompts.', true);
  } catch (e) {
    html = pagina('No se pudo registrar', 'El servicio local no respondió (' + String(e.message).slice(0, 120) + '). Probá de nuevo en un rato.', false);
  }
}
return [{ json: { html } }];
